            ('religion:restore'::text, 'religion'::text, 'restore'::text, 'Restore religion'::text),
            ('religion:update'::text, 'religion'::text, 'update'::text, 'Update religion'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
